INSERT INTO `blog_categories` VALUES (1,'Automation','automation','Practical guides for WhatsApp automation, routing, and team workflows.',1,1,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(2,'Growth','growth','Broadcast campaigns, segmentation, and customer lifecycle messaging.',2,1,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(3,'Product','product','CRM dashboards, reporting, and product strategy for WhatsApp teams.',3,1,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(4,'Support','support','Customer support, chatbots, and handoff best practices.',4,1,'2026-09-21 16:23:48','2026-09-21 16:23:48');
/*!40000 ALTER TABLE `blog_categories` ENABLE KEYS */;
UNLOCK TABLES;

