INSERT INTO `frontend_sections` VALUES (1,'Homepage Hero','homepage-hero','home_hero','published','{\"logos\": [{\"alt\": \"Vercel\", \"fallback_src\": \"assets/logos/vercel.svg\", \"logo_media_id\": null}, {\"alt\": \"Stripe\", \"fallback_src\": \"assets/logos/stripe.svg\", \"logo_media_id\": null}, {\"alt\": \"Figma\", \"fallback_src\": \"assets/logos/figma.svg\", \"logo_media_id\": null}, {\"alt\": \"Linear\", \"fallback_src\": \"assets/logos/linear.svg\", \"logo_media_id\": null}, {\"alt\": \"Notion\", \"fallback_src\": \"assets/logos/notion.svg\", \"logo_media_id\": null}, {\"alt\": \"Shopify\", \"fallback_src\": \"assets/logos/shopify.svg\", \"logo_media_id\": null}, {\"alt\": \"Cloudflare\", \"fallback_src\": \"assets/logos/cloudflare.svg\", \"logo_media_id\": null}, {\"alt\": \"Airbnb\", \"fallback_src\": \"assets/logos/airbnb.svg\", \"logo_media_id\": null}, {\"alt\": \"Spotify\", \"fallback_src\": \"assets/logos/spotify.svg\", \"logo_media_id\": null}, {\"alt\": \"Discord\", \"fallback_src\": \"assets/logos/discord.svg\", \"logo_media_id\": null}, {\"alt\": \"Google Cloud\", \"fallback_src\": \"assets/logos/googlecloud.svg\", \"logo_media_id\": null}, {\"alt\": \"Docker\", \"fallback_src\": \"assets/logos/docker.svg\", \"logo_media_id\": null}, {\"alt\": \"Kubernetes\", \"fallback_src\": \"assets/logos/kubernetes.svg\", \"logo_media_id\": null}, {\"alt\": \"TypeScript\", \"fallback_src\": \"assets/logos/typescript.svg\", \"logo_media_id\": null}, {\"alt\": \"Next.js\", \"fallback_src\": \"assets/logos/nextdotjs.svg\", \"logo_media_id\": null}, {\"alt\": \"React\", \"fallback_src\": \"assets/logos/react.svg\", \"logo_media_id\": null}, {\"alt\": \"Tailwind CSS\", \"fallback_src\": \"assets/logos/tailwindcss.svg\", \"logo_media_id\": null}], \"subheading\": \"Classic is a senior product team for founders and operators. From discovery to launch — clean UI, scalable code, one timeline.\", \"stat_1_label\": \"Products shipped\", \"stat_1_value\": \"120+\", \"stat_2_label\": \"Average MVP\", \"stat_2_value\": \"8 wks\", \"stat_3_label\": \"Client rating\", \"stat_3_value\": \"4.9/5\", \"caption_words\": \"SaaS platforms\\nweb apps\\nmobile apps\\nMVPs\", \"caption_prefix\": \"We ship\", \"heading_accent\": \"SaaS, web and mobile\", \"eyebrow_message\": \"Now booking Q3 builds — 2 slots left\", \"marquee_eyebrow\": \"Trusted by teams that ship at\", \"heading_line_one\": \"We build scalable\", \"heading_line_two\": \"products.\", \"primary_cta_link\": \"#contact\", \"primary_cta_text\": \"Start a Project\", \"uptime_chip_text\": \"99.98% uptime\", \"eyebrow_badge_text\": \"Live\", \"secondary_cta_link\": \"#showreel\", \"secondary_cta_text\": \"Watch Showreel\", \"deploy_chip_version\": \"v2.4.1 · production\"}','Primary hero section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(2,'Homepage About','homepage-about','home_about','published','{\"cta_link\": \"/about\", \"cta_text\": \"About Classic\", \"est_text\": \"EST · 2014 · SOFTIVUS\", \"intro_body\": \"Classic is a senior product team for founders and operators. From discovery to launch, we ship modern digital products with clean UI, scalable code, and a single delivery timeline.\", \"video_link\": \"https://www.youtube.com/watch?v=LXb3EKWsInQ\", \"video_year\": \"2024\", \"video_label\": \"Showreel · 2 min\", \"video_title\": \"How we ship products\", \"badge_number\": \"10+\", \"eyebrow_text\": \"About our company\", \"heading_accent\": \"SaaS, web, and mobile\", \"differentiators\": [{\"label\": \"Senior product team\"}, {\"label\": \"Engineering taste\"}, {\"label\": \"120+ products shipped\"}, {\"label\": \"Remote-first, global\"}], \"body_paragraph_1\": \"We focus on smart, efficient, high-performance digital products. Strong expertise across product strategy, UI/UX, web and mobile engineering, and platform integrations — combined into one team that owns delivery from kickoff to ship.\", \"body_paragraph_2\": \"Our work blends product strategy and engineering taste so the outcome looks the way it should and performs the way it must — for founders, operators, and growing companies.\", \"heading_line_one\": \"We build complete\", \"heading_line_two\": \"products — end to end.\", \"arch_caption_body\": \"Same senior engineers and designers from kickoff to launch — no junior handoffs.\", \"arch_caption_title\": \"A team that owns the outcome.\", \"arch_image_media_id\": null, \"differentiators_heading\": \"What makes us different\", \"video_card_image_media_id\": null}','About section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(3,'Homepage Services','homepage-services','home_services','published','{\"cta_link\": \"#services\", \"cta_text\": \"Explore all services\", \"eyebrow_text\": \"Services\", \"heading_line_one\": \"Engineering teams\", \"heading_highlight\": \"that ship.\"}','Services section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(4,'Homepage Stats','homepage-stats','home_stats_number','published','{\"card1_badge\": \"2x · YoY\", \"card1_label\": \"Annual success rate\", \"card2_badge\": \"1x+ · lifetime\", \"card2_label\": \"Projects completed\", \"card1_target\": \"98%\", \"card2_target\": \"23K\", \"background_image_media_id\": null}','Stats section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(5,'Homepage Solutions','homepage-solutions','home_solutions','published','{\"subheading\": \"Whatever the model — SaaS, marketplace, mobile, fintech — we ship the right architecture for the way it actually has to grow.\", \"eyebrow_text\": \"Solutions\", \"heading_line_one\": \"One team,\", \"heading_highlight\": \"six product shapes.\"}','Solutions section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(6,'Homepage Marquee','homepage-marquee','home_marquee','published','{\"phrases\": [{\"text\": \"Build with intent\"}, {\"text\": \"Ship like a senior team\"}, {\"text\": \"Design that survives engineering\"}, {\"text\": \"Engineered for the way it grows\"}, {\"text\": \"From discovery to launch\"}], \"badge_text\": \"SOFTIVUS · BUILD · SHIP · SOFTIVUS · BUILD · SHIP ·\"}','Marquee section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(7,'Homepage Why Us','homepage-why-us','home_why_us','published','{\"pillars\": [{\"icon\": \"ph-users\", \"size\": \"hero\", \"color\": \"blue\", \"title\": \"A senior team, not an agency funnel.\", \"number\": \"01\", \"checklist\": \"No outsourcing layers\\n9+ years average experience\\nSame team start to finish\\n4–6 specialists per build\", \"stat_label\": \"\", \"stat_value\": \"\", \"description\": \"Same senior engineers and designers from kickoff to launch.\"}, {\"icon\": \"ph-lightning\", \"size\": \"std\", \"color\": \"green\", \"title\": \"Eight weeks, not eight quarters.\", \"number\": \"02\", \"checklist\": \"\", \"stat_label\": \"avg MVP timeline\", \"stat_value\": \"8 wks\", \"description\": \"Discovery to launch on one timeline.\"}, {\"icon\": \"ph-key\", \"size\": \"std\", \"color\": \"navy\", \"title\": \"You own the code and the keys.\", \"number\": \"03\", \"checklist\": \"\", \"stat_label\": \"repo + infra at handoff\", \"stat_value\": \"Yours\", \"description\": \"Your GitHub, your cloud, your secrets.\"}, {\"icon\": \"ph-arrows-clockwise\", \"size\": \"std\", \"color\": \"navy\", \"title\": \"Weekly demos, not quarterly reveals.\", \"number\": \"04\", \"checklist\": \"\", \"stat_label\": \"avg feedback loop\", \"stat_value\": \"7d\", \"description\": \"Working software every week.\"}, {\"icon\": \"ph-activity\", \"size\": \"std\", \"color\": \"blue\", \"title\": \"Observability built in, not bolted on.\", \"number\": \"05\", \"checklist\": \"\", \"stat_label\": \"telemetry live\", \"stat_value\": \"Day 1\", \"description\": \"Logs, traces, and analytics from day one.\"}, {\"icon\": \"ph-receipt\", \"size\": \"std\", \"color\": \"green\", \"title\": \"Honest pricing, no surprise invoices.\", \"number\": \"06\", \"checklist\": \"\", \"stat_label\": \"change-order quote\", \"stat_value\": \"24h\", \"description\": \"Fixed-scope sprints with a clear rate card.\"}, {\"icon\": \"ph-handshake\", \"size\": \"wide\", \"color\": \"blue\", \"title\": \"Built for the long arc, not just launch.\", \"number\": \"07\", \"checklist\": \"Same team for v2 and beyond\\nRetainer or pay-as-you-need\\nQuarterly roadmap reviews\\nDirect line to engineers\", \"stat_label\": \"\", \"stat_value\": \"\", \"description\": \"Same team for v2 and the year-two roadmap.\"}], \"subheading\": \"What separates Classic is what we don\'t do — no junior handoffs, no locked code, no quarter-long timelines, no surprise invoices.\", \"footer_text\": \"Sound like the team you\'d want to build with?\", \"eyebrow_text\": \"Why Classic\", \"footer_email\": \"support.com\", \"footer_cta_link\": \"#contact\", \"footer_cta_text\": \"Book a 30-min scope call\", \"heading_line_one\": \"Built like a senior product team.\", \"heading_line_two\": \"Priced like an honest one.\", \"footer_email_label\": \"24/7 Available\"}','Why choose us section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(8,'Homepage How Work','homepage-how-work','home_how_work','published','{\"phases\": [{\"icon\": \"ph-compass\", \"title\": \"Understand the why before the what.\", \"number\": \"01\", \"duration\": \"1 week\", \"description\": \"Stakeholder interviews, technical audit, and a written scope doc. We leave with a one-page brief and a milestone plan you can sign off on.\", \"phase_label\": \"Discovery\", \"deliverables\": \"Discovery brief\\nTechnical audit\\nMilestone plan\\nRisk register\"}, {\"icon\": \"ph-palette\", \"title\": \"Hi-fi designs ready to build, not pitch.\", \"number\": \"02\", \"duration\": \"2 weeks\", \"description\": \"Research-backed flows, design tokens, and motion specs in Figma. Every screen reviewed against the engineering plan so it survives the build.\", \"phase_label\": \"Design\", \"deliverables\": \"Hi-fi mockups\\nDesign system tokens\\nInteraction specs\\nAccessibility audit\"}, {\"icon\": \"ph-code\", \"title\": \"Working software every week, not every quarter.\", \"number\": \"03\", \"duration\": \"4–6 weeks\", \"description\": \"Two-week sprints with a public preview environment. Telemetry from sprint one. Demo every Friday with a clear changelog.\", \"phase_label\": \"Build\", \"deliverables\": \"Preview environment\\nWeekly demos\\nTelemetry pipeline\\nContinuous deploys\"}, {\"icon\": \"ph-rocket\", \"title\": \"Production-ready, observable, and yours.\", \"number\": \"04\", \"duration\": \"1 week\", \"description\": \"Deploy to your cloud, your domain, your repo. Runbook, on-call rotation, and a post-launch report on day three.\", \"phase_label\": \"Launch\", \"deliverables\": \"Production deploy\\nRunbook + alerts\\nDay-3 launch report\\nCode handover\"}, {\"icon\": \"ph-trend-up\", \"title\": \"Same team, year-two roadmap.\", \"number\": \"05\", \"duration\": \"Ongoing\", \"description\": \"Quarterly roadmap reviews, retainer or pay-as-you-need engineering, and direct-line access to the team that shipped v1.\", \"phase_label\": \"Scale\", \"deliverables\": \"Quarterly review\\nRetainer engineering\\nRoadmap planning\\nOn-call support\"}], \"subheading\": \"From discovery to year-two roadmap — the same engineers and designers from kickoff to scale, with a clear deliverable at every step.\", \"eyebrow_text\": \"How we work\", \"heading_line_one\": \"Five phases.\", \"heading_line_two\": \"One team. One timeline.\"}','Process section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(9,'Homepage Stack','homepage-stack','home_stack','published','{\"subheading\": \"Every technology earns its place. No bloat, no trend-chasing — just the stack that ships fastest and scales longest.\", \"eyebrow_text\": \"Technology stack\", \"heading_line_one\": \"The tools we ship with —\", \"heading_highlight\": \"every one, opinionated.\"}','Technology stack section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(10,'Homepage Testimonials','homepage-testimonials','home_testimonials','published','{\"subheading\": \"A decade of senior product engineering — measured in launches, retention, and the long arc of teams we still work with.\", \"eyebrow_text\": \"What teams say\", \"heading_line_one\": \"Trusted by founders\", \"heading_line_two\": \"who actually shipped.\"}','Testimonials section for the homepage.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(11,'Homepage Blog','homepage-blog','home_blog','published','{\"cta_link\": \"/blog\", \"cta_text\": \"View all posts\", \"subheading\": \"Practical WhatsApp automation, CRM, broadcast, and chatbot ideas for teams that want better customer conversations.\", \"eyebrow_text\": \"From the Blog\", \"heading_line_one\": \"Insights &\", \"heading_highlight\": \"articles\"}','Homepage blog preview section.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(12,'Homepage Products','homepage-products','home_products','published','{\"cta_link\": \"/products\", \"cta_text\": \"View all products\", \"subheading\": \"Browse active products from connected storefronts and start a WhatsApp order with the store owner.\", \"eyebrow_text\": \"WhatsApp Catalog\", \"product_limit\": 4, \"heading_line_one\": \"Latest\", \"heading_highlight\": \"products\"}','Homepage commerce product preview section.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(13,'Global FAQ','global-faq','global_faq','published','{\"subheading\": \"The questions founders ask in the first 30-minute scope call.\", \"call_card_body\": \"30-minute scope call with someone who would actually build it. Usually within 48 hours.\", \"call_card_title\": \"Talk to a senior engineer\", \"email_card_body\": \"Send a one-pager and we\'ll come back with a written response within two working days.\", \"email_card_email\": \"hello.com\", \"email_card_title\": \"Drop us a brief\", \"heading_line_one\": \"Common questions,\", \"heading_line_two\": \"clear answers.\", \"call_card_cta_link\": \"#book-call\", \"call_card_cta_text\": \"Book a call\", \"call_card_engineers_text\": \"8 senior engineers · all on call\"}','Reusable FAQ section across the frontend.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(14,'Blog Hero','blog-hero','blog_hero','published','{\"heading\": \"WhatsApp marketing insights for growing teams\", \"subheading\": \"Guides on automation, broadcasts, chatbots, CRM workflows, and customer messaging that feels personal at scale.\", \"eyebrow_text\": \"WaPro Blog\"}','Hero section for the blog page.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(15,'Blog Featured','blog-featured','blog_featured','published','{\"heading\": \"Start with the latest playbook\", \"eyebrow_text\": \"Featured\"}','Featured articles section for the blog page.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(16,'Blog Archive','blog-archive','blog_archive','published','{\"heading\": \"All articles\", \"subheading\": \"Browse practical guides for WhatsApp marketing, support automation, campaign operations, and customer growth.\", \"eyebrow_text\": \"Archive\"}','All articles grid section for the blog page.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(17,'Blog Newsletter','blog-newsletter','blog_newsletter','published','{\"heading\": \"Get WhatsApp growth notes in your inbox\", \"subheading\": \"Practical automation, CRM, and campaign ideas for teams that use messaging every day.\", \"button_text\": \"Subscribe\", \"eyebrow_text\": \"Newsletter\"}','Newsletter signup section for the blog page.','[]',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48'),(18,'FAQ Hero','faq-hero','faq_hero','published','{\"eyebrow\": \"FAQ\", \"description\": \"Clear answers about process, pricing, collaboration, ownership, and support.\", \"heading_line\": \"Questions t