INSERT INTO `notification_templates` VALUES (1,'welcome','Welcome','Sent to new users after registration','Welcome to {{site_name}}, {{user_name}}!','<p>Hello {{user_name}},</p><p>Welcome to {{site_name}}! Your account has been created successfully.</p><p>Click the button below to get started.</p>',NULL,'Welcome, {{user_name}}!','Your account has been created successfully. Start exploring the platform.',NULL,NULL,'[\"email\", \"in_app\"]','{\"login_url\": \"URL to the login page\", \"user_name\": \"The registered user\'s name\"}',1,'2026-09-21 16:23:48','2026-09-21 16:23:48',NULL),(2,'password-changed','Password Changed','Sent when a user changes their password','Your password has been changed','<p>Hi {{user_name}},</p><p>Your password was successfully changed on {{changed_at}}.</p><p>If you did not make this change, please contact support immediately.</p>',NULL,NULL,NULL,NULL,NULL,'[\"email\"]','{\"user_name\": \"The user\'s name\", \"changed_at\": \"Date and time of the change\"}',1,'2026-09-21 16:23:48','2026-09-21 16:23:48',NULL),(3,'subscription-expiring-soon','Subscription Expiring Soon','Sent to workspace owners one day before their subscription expires','Your {{plan_name}} plan expires soon','<p>Hello {{user_name}},</p><p>Your {{plan_name}} plan for {{workspace_name}} expires on {{expires_at}}.</p><p>Please renew your subscription to keep your services running.</p>','{{site_name}}: Your {{plan_name}} plan expires on {{expires_at}}. Renew: {{renew_url}}','Your plan expires soon','{{plan_name}} for {{workspace_name}} expires on {{expires_at}}.','Your plan expires soon','{{plan_name}} expires on {{expires_at}}.','[\"email\", \"sms\", \"in_app\", \"web_push\", \"mobile_push\"]','{\"plan_name\": \"The current plan name\", \"renew_url\": \"The subscription renewal URL\", \"user_name\": \"The workspace owner name\", \"expires_at\": \"The subscription expiry date\", \"days_remaining\": \"Days remaining before expiry\", \"workspace_name\": \"The workspace name\"}',1,'2026-09-21 16:23:48','2026-09-21 16:23:48',NULL),(4,'subscription-expired','Subscription Expired','Sent to workspace owners when their subscription is marked expired','Your {{plan_name}} plan has expired','<p>Hello {{user_name}},</p><p>Your {{plan_name}} plan for {{workspace_name}} expired on {{expires_at}}.</p><p>Your workspace is now read-only until you renew.</p>','{{site_name}}: Your {{plan_name}} plan has expired. Renew: {{renew_url}}','Your plan has expired','{{workspace_name}} is read-only until you renew {{plan_name}}.','Your plan has expired','{{workspace_name}} is read-only until renewal.','[\"email\", \"sms\", \"in_app\", \"web_push\", \"mobile_push\"]','{\"plan_name\": \"The expired plan name\", \"renew_url\": \"The subscription renewal URL\", \"user_name\": \"The workspace owner name\", \"expires_at\": \"The subscription expiry date\", \"days_remaining\": \"Days remaining before expiry\", \"workspace_name\": \"The workspace name\"}',1,'2026-09-21 16:23:48','2026-09-21 16:23:48',NULL);
