INSERT INTO `pages` VALUES (1,'Home','home','published','WaPro — WhatsApp marketing, automation, and CRM platform.','landing','[]',1,1,'WhatsApp Marketing, Automation & CRM - WaPro','Run WhatsApp Cloud API campaigns, smart replies, chatbots, contacts, automations, and reports from one SaaS workspace.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(2,'Team','team','published','Meet the team behind Classic.','default','[]',1,0,'Team — Classic','Meet the engineers, designers, and product builders behind Classic. A focused team building world-class digital products.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(3,'Careers','careers','published','Join a tight-knit team building world-class digital products. See open roles at Classic.','default','[]',1,0,'Careers — Classic','Join a tight-knit team building world-class digital products. See open roles at Classic.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(4,'About Us','about','published','Learn who we are, what drives us, and how we\'ve been building world-class digital products since 2018.','default','[]',1,0,'About Us — Classic','Learn who we are, what drives us, and how we\'ve been building world-class digital products since 2018.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(5,'Service Category Template','service-category-template','published','Template page that defines the sections shown on all service category detail pages.','service_category','[]',1,0,'Service Category Template',NULL,NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(6,'Project Category Template','project-category-template','published','Template page that defines the sections shown on all project category detail pages.','project_category','[]',1,0,'Project Category Template',NULL,NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(7,'Contact','contact','published','Talk to the WaPro team. Questions about features, pricing, or getting set up.','default','[]',1,0,'Contact - WaPro','Questions about features, pricing, or getting set up? Send us a message and we\'ll get back within one business day.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(8,'FAQ','faq','published','Answers to the most common questions about Classic — process, pricing, ownership, and support.','default','[]',1,0,'FAQ — Classic','Answers to the most common questions about Classic — process, pricing, ownership, and support.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(9,'Support','support','published','Get help from the Classic support team. Browse FAQs, submit a ticket, or reach out via live chat.','default','[]',1,0,'Support — Classic','Get help from the Classic support team. Browse FAQs, submit a ticket, or reach out via live chat. We\'re here Saturday to Thursday, 5AM–2PM GMT.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(10,'Blog','blog','published','WhatsApp marketing, automation, chatbot, and CRM insights from WaPro.','default','[]',1,0,'WhatsApp Marketing Blog - WaPro','Read WaPro guides on WhatsApp automation, broadcast campaigns, chatbots, CRM workflows, and customer messaging.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(11,'Features','features','published','Explore every WaPro module — broadcasting, automation, chatbot, contacts, and more.','default','[]',1,0,'Features - WaPro','Campaigns, automation, a shared inbox, contacts, and reporting — built for the way teams run WhatsApp at scale.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(12,'FAQs','faqs','published','Everything you need to know about WaPro — from getting set up to billing and the API.','default','[]',1,0,'FAQs - WaPro','Answers to the most common questions about WaPro — setup, billing, messaging, and API.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(13,'Privacy Policy','privacy-policy','published','How WaPro collects, uses, and protects personal information.','default','[]',1,0,'Privacy Policy - WaPro','Learn how WaPro collects, uses, shares, and protects personal information.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(14,'Terms & Conditions','terms-and-conditions','published','The terms that govern access to and use of WaPro.','default','[]',1,0,'Terms & Conditions - WaPro','Review the terms and conditions that apply when using WaPro.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(15,'Confidentiality & Privacy','confidentiality-privacy','published','How WaPro treats customer workspace information and confidential data.','default','[]',1,0,'Confidentiality & Privacy - WaPro','Learn how WaPro handles customer workspace information, message data, and confidential operational details.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(16,'Legal Information','legal-information','published','General company, compliance, and legal contact information for WaPro.','default','[]',1,0,'Legal Information - WaPro','Find general company, compliance, and legal contact information for WaPro.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48'),(17,'Cookie Policy','cookie-policy','published','How WaPro uses cookies and similar technologies.','default','[]',1,0,'Cookie Policy - WaPro','Learn how WaPro uses cookies and similar technologies on its website and services.',NULL,'2026-09-21 16:23:48','2026-09-21 16:23:48','2026-09-21 16:23:48');
